// Accept a file from the form or an email attachment and expose it as binary 'invoice'.
const bin = $input.item.binary || {};
const keys = Object.keys(bin);
const key = keys.find(k => (bin[k].mimeType || '').includes('pdf') || (bin[k].fileName || '').toLowerCase().endsWith('.pdf')) || keys[0];
if (!key) {
  throw new Error('No PDF found in the upload or email');
}
const from = $json.from;
return {
  json: {
    source: from ? 'email' : 'form',
    file_name: bin[key].fileName || 'invoice.pdf',
    email_from: typeof from === 'string' ? from : (from?.text ?? null),
    email_subject: $json.subject ?? null
  },
  binary: { invoice: bin[key] }
};

