{
  "type": "object",
  "properties": {
    "supplier_name": { "type": "string", "description": "Name of the company that issued the invoice" },
    "supplier_vat": { "type": "string", "description": "Supplier VAT number, e.g. BE0123456789. Empty string if absent" },
    "invoice_number": { "type": "string" },
    "invoice_date": { "type": "string", "description": "Invoice date as YYYY-MM-DD" },
    "due_date": { "type": "string", "description": "Payment due date as YYYY-MM-DD. Empty string if absent" },
    "currency": { "type": "string", "description": "ISO 4217 code, e.g. EUR" },
    "net_amount": { "type": "number", "description": "Total excluding VAT" },
    "vat_amount": { "type": "number", "description": "Total VAT amount" },
    "total_amount": { "type": "number", "description": "Total including VAT, the amount to pay" },
    "iban": { "type": "string", "description": "Supplier bank account IBAN without spaces. Empty string if absent" }
  },
  "required": ["supplier_name", "invoice_number", "total_amount"]
}

