// Normalise the AI output and run deterministic checks. Output keys match demo.invoices columns.
const o = $json.output ?? {};
const src = $('Normalize input').item.json;

const num = v => {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return Math.round(v * 100) / 100;
  let s = String(v).replace(/[^\d,.-]/g, '');
  if (s.includes(',') && s.lastIndexOf(',') > s.lastIndexOf('.')) s = s.replace(/\./g, '').replace(',', '.');
  else s = s.replace(/,/g, '');
  const n = parseFloat(s);
  return Number.isNaN(n) ? null : Math.round(n * 100) / 100;
};
const date = v => (/^\d{4}-\d{2}-\d{2}$/.test(v || '') ? v : null);
const text = v => (v === undefined || v === null || String(v).trim() === '' ? null : String(v).trim());

// Belgian VAT / enterprise number: 10 digits, last 2 = 97 - (first 8 mod 97)
const vat = (o.supplier_vat || '').toUpperCase().replace(/[^A-Z0-9]/g, '') || null;
let vat_valid = null;
if (vat && vat.startsWith('BE')) {
  let d = vat.slice(2);
  if (d.length === 9) d = '0' + d;
  vat_valid = /^[01]\d{9}$/.test(d) && 97 - (parseInt(d.slice(0, 8), 10) % 97) === parseInt(d.slice(8), 10);
}

// IBAN mod-97 check
const iban = (o.iban || '').toUpperCase().replace(/[^A-Z0-9]/g, '') || null;
const ibanValid = s => {
  if (!/^[A-Z]{2}\d{2}[A-Z0-9]{8,30}$/.test(s)) return false;
  const r = (s.slice(4) + s.slice(0, 4)).replace(/[A-Z]/g, c => String(c.charCodeAt(0) - 55));
  let m = 0;
  for (const ch of r) m = (m * 10 + Number(ch)) % 97;
  return m === 1;
};

const net = num(o.net_amount);
const tax = num(o.vat_amount);
const total = num(o.total_amount);
const invoice_date = date(o.invoice_date);
const due_date = date(o.due_date);

const reasons = [];
if (!text(o.invoice_number)) reasons.push('missing invoice number');
if (total === null) reasons.push('missing total');
if (net !== null && tax !== null && total !== null && Math.abs(net + tax - total) > 0.02) reasons.push(`net + VAT (${(net + tax).toFixed(2)}) does not match total (${total.toFixed(2)})`);
if (vat_valid === false) reasons.push('invalid Belgian VAT number');
if (iban && !ibanValid(iban)) reasons.push('invalid IBAN');
if (!invoice_date) reasons.push('missing or unreadable invoice date');
if (invoice_date && due_date && due_date < invoice_date) reasons.push('due date before invoice date');

return {
  json: {
    source: src.source,
    file_name: src.file_name,
    supplier_name: text(o.supplier_name),
    supplier_vat: vat,
    vat_valid,
    invoice_number: text(o.invoice_number),
    invoice_date,
    due_date,
    currency: (text(o.currency) || 'EUR').toUpperCase().slice(0, 3),
    net_amount: net,
    vat_amount: tax,
    total_amount: total,
    iban,
    needs_review: reasons.length > 0,
    review_reasons: reasons.length ? reasons.join('; ') : null,
    raw: JSON.stringify(o)
  }
};
